import os,time,json
children=[]
try:
 for _ in range(80):
  try:pid=os.fork()
  except OSError as e:print('fork_denied',e.errno,'children',len(children),flush=True);break
  if pid==0:time.sleep(20);os._exit(0)
  children.append(pid)
 print('pids_events',open('/sys/fs/cgroup/pids.events').read(),flush=True)
finally:
 for pid in children:os.kill(pid,9)
 for pid in children:os.waitpid(pid,0)

